public CompletableFuture<PaymentResult> processPayment(PaymentRequest request) {
    return CompletableFuture.supplyAsync(() -> paymentGateway.charge(request))
        .thenApply(res -> {
            if (!res.isSuccessful()) {
                throw new PaymentFailedException("Insufficient funds");
            }
            return res;
        });
}

